list_trash.code:
use WebCommander\Resources\Trash\Trash;

$response = Trash::listTrash($client, ['type' => 'Category', 'search' => 'spring', 'sort' => 'name', 'order' => 'asc', 'limit' => 20]);

foreach ($response->map['items'] as $item) {
    echo $item['id'], ' ', $item['type'], ' ', $item['name'], ' ', $item['removed_at'], PHP_EOL;
}
echo $response->map['pagination']['has_next'] ? 'more pages' : 'last page', PHP_EOL;

list_trash_types.code:
use WebCommander\Resources\Trash\Trash;

$response = Trash::listTrashTypes($client);

echo implode(', ', array_column($response->map['types'], 'type')), PHP_EOL;

restore_trash_item.code:
use WebCommander\Resources\Trash\Trash;

$response = Trash::restoreTrashItem($client, 'Category', 1234);

$item = $response->map['item'];
echo $item['type'], ' ', $item['id'], ' ', $item['name'], ' restored', PHP_EOL;

bulk_restore_trash.code:
use WebCommander\Resources\Trash\Trash;

$response = Trash::bulkRestoreTrash($client, ['items' => [
    ['type' => 'Category', 'id' => 1234],
    ['type' => 'BlogPost', 'id' => 99],
]]);

echo count($response->map['restored']), ' restored, ', count($response->map['failed']), ' failed', PHP_EOL;
foreach ($response->map['failed'] as $failure) {
    echo $failure['type'], ' ', $failure['id'], ': ', $failure['code'], ' ', $failure['message'], PHP_EOL;
}

bulk_delete_trash.code:
use WebCommander\Resources\Trash\Trash;

$response = Trash::bulkDeleteTrash($client, ['items' => [
    ['type' => 'Category', 'id' => 1234],
    ['type' => 'Category', 'id' => 1229],
]]);

echo count($response->map['deleted']), ' deleted, ', count($response->map['failed']), ' failed', PHP_EOL;
foreach ($response->map['failed'] as $failure) {
    echo $failure['type'], ' ', $failure['id'], ': ', $failure['code'], ' ', $failure['message'], PHP_EOL;
}
